# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GENETİK ŞİFRE: ÜÇLÜ NÜKLEOTİT SİSTEMİ (64 KODON)</text>\n  <!-- DNA Kalip -->\n  <rect x="30" y="45" width="200" height="90" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="130" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">DNA (Kalıp Zincir)</text>\n  <text x="130" y="90" text-anchor="middle" font-size="12" fill="#1e3a8a">4 Çeşit Baz (A, T, G, S)</text>\n  <text x="130" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">4³ = 64 Genetik Kodon</text>\n  <text x="130" y="126" text-anchor="middle" font-size="11" fill="#3b82f6">Örnek: 3\'-T A C - A T T-5\'</text>\n  <!-- Ok 1 -->\n  <line x1="230" y1="90" x2="265" y2="90" stroke="#475569" stroke-width="2"/>\n  <polygon points="265,85 275,90 265,95" fill="#475569"/>\n  <!-- mRNA -->\n  <rect x="275" y="45" width="200" height="90" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="375" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">mRNA (Kodonlar)</text>\n  <text x="375" y="90" text-anchor="middle" font-size="12" fill="#14532d">4 Çeşit Baz (A, U, G, S)</text>\n  <text x="375" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">61 Anlamlı + 3 Durdurucu</text>\n  <text x="375" y="126" text-anchor="middle" font-size="11" fill="#16a34a">Örnek: 5\'-A U G - U A A-3\'</text>\n  <!-- Ok 2 -->\n  <line x1="475" y1="90" x2="510" y2="90" stroke="#475569" stroke-width="2"/>\n  <polygon points="510,85 520,90 510,95" fill="#475569"/>\n  <!-- tRNA -->\n  <rect x="520" y="45" width="150" height="90" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="595" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">tRNA (Antikodon)</text>\n  <text x="595" y="90" text-anchor="middle" font-size="12" fill="#78350f">En Fazla 61 Çeşit</text>\n  <text x="595" y="110" text-anchor="middle" font-size="11" fill="#b45309">Durdurucu kodonların</text>\n  <text x="595" y="125" text-anchor="middle" font-size="11" fill="#b45309">tRNA karşılığı yoktur</text>\n  <!-- Alt Kutular -->\n  <rect x="30" y="152" width="310" height="92" rx="8" fill="#ecfdf5" stroke="#059669" stroke-width="1.8"/>\n  <text x="185" y="175" text-anchor="middle" font-size="13" font-weight="bold" fill="#065f46">BAŞLANGIÇ KODONU: AUG</text>\n  <text x="185" y="196" text-anchor="middle" font-size="12" fill="#047857">• Metiyonin amino asidini şifreler.</text>\n  <text x="185" y="215" text-anchor="middle" font-size="12" fill="#047857">• Protein sentezini başlatan ilk sinyali verir.</text>\n  <text x="185" y="234" text-anchor="middle" font-size="11" fill="#059669">Tek kodonla şifrelenenler: Metiyonin (AUG), Triptofan (UGG)</text>\n\n  <rect x="360" y="152" width="310" height="92" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="515" y="175" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">DURDURUCU KODONLAR: UAA, UAG, UGA</text>\n  <text x="515" y="196" text-anchor="middle" font-size="12" fill="#b91c1c">• Hiçbir amino asidi şifrelemezler.</text>\n  <text x="515" y="215" text-anchor="middle" font-size="12" fill="#b91c1c">• Karşılıklarında tRNA antikodonu bulunmaz.</text>\n  <text x="515" y="234" text-anchor="middle" font-size="11" fill="#dc2626">Sonlandırma faktörü bağlanarak sentezi bitirir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TRANSKRİPSİYON VE TRANSLASYON SÜRECİ</text>\n  <!-- Sol: Transkripsiyon -->\n  <rect x="25" y="42" width="315" height="202" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. TRANSKRİPSİYON (Yazılım)</text>\n  <text x="40" y="90" font-size="12" fill="#1e3a8a">• Enzim: RNA Polimeraz (Helikaz gerekmez)</text>\n  <text x="40" y="112" font-size="12" fill="#1e3a8a">• DNA\'nın ilgili gen bölgesi geçici açılır.</text>\n  <text x="40" y="134" font-size="12" fill="#1e3a8a">• Kalıp zincir karşısına mRNA sentezlenir.</text>\n  <rect x="45" y="150" width="275" height="78" rx="6" fill="#ffffff" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="182" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">DNA Kalıp → mRNA Eşleşmesi</text>\n  <text x="182" y="194" text-anchor="middle" font-size="12" fill="#0f172a">Adenin (A) → Urasil (U) | Timin (T) → Adenin (A)</text>\n  <text x="182" y="214" text-anchor="middle" font-size="12" fill="#0f172a">Guanin (G) → Sitozin (S) | Sitozin (S) → Guanin (G)</text>\n  <!-- Sag: Translasyon -->\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#f0fdf4" stroke="#22c55e" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. TRANSLASYON (Okuma / Çeviri)</text>\n  <text x="375" y="90" font-size="12" fill="#14532d">• Yer: Ribozom (Tüm canlılarda ortak)</text>\n  <text x="375" y="112" font-size="12" fill="#14532d">• mRNA küçük alt birime bağlanır, AUG okunur.</text>\n  <text x="375" y="134" font-size="12" fill="#14532d">• Büyük alt birim katılır, peptit bağları kurulur.</text>\n  <rect x="380" y="150" width="275" height="78" rx="6" fill="#ffffff" stroke="#86efac" stroke-width="1.5"/>\n  <text x="517" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Dehidrasyon Bağıntısı (n amino asit için)</text>\n  <text x="517" y="194" text-anchor="middle" font-size="12" fill="#0f172a">Kurulan Peptit Bağı Sayısı = n - 1</text>\n  <text x="517" y="214" text-anchor="middle" font-size="12" fill="#0f172a">Açığa Çıkan Su Molekülü Sayısı = n - 1</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SANTRAL DOGMA AKIŞI VE POLİZOM (POLİRİBOZOM)</text>\n  <!-- Santral Dogma -->\n  <rect x="40" y="48" width="130" height="65" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="105" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e40af">DNA</text>\n  <text x="105" y="96" text-anchor="middle" font-size="11" fill="#1d4ed8">Replikasyon (Eşlenme)</text>\n\n  <line x1="170" y1="80" x2="265" y2="80" stroke="#2563eb" stroke-width="2.5"/>\n  <polygon points="265,75 277,80 265,85" fill="#2563eb"/>\n  <text x="222" y="70" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Transkripsiyon</text>\n\n  <rect x="277" y="48" width="130" height="65" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="342" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#166534">mRNA</text>\n  <text x="342" y="96" text-anchor="middle" font-size="11" fill="#15803d">Şifre Taşıyıcı</text>\n\n  <line x1="407" y1="80" x2="502" y2="80" stroke="#16a34a" stroke-width="2.5"/>\n  <polygon points="502,75 514,80 502,85" fill="#16a34a"/>\n  <text x="460" y="70" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Translasyon</text>\n\n  <rect x="514" y="48" width="145" height="65" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="586" y="76" text-anchor="middle" font-size="14" font-weight="bold" fill="#92400e">PROTEİN</text>\n  <text x="586" y="96" text-anchor="middle" font-size="11" fill="#b45309">Polipeptit Zinciri</text>\n\n  <!-- Polizom Kutu -->\n  <rect x="40" y="132" width="620" height="110" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="155" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">POLİZOM (POLİRİBOZOM) MEKANİZMASI</text>\n  <line x1="80" y1="195" x2="420" y2="195" stroke="#dc2626" stroke-width="4"/>\n  <text x="70" y="218" font-size="11" font-weight="bold" fill="#dc2626">mRNA (5\' → 3\')</text>\n  <circle cx="150" cy="195" r="18" fill="#d8b4fe" stroke="#7e22ce" stroke-width="2"/>\n  <circle cx="240" cy="195" r="18" fill="#d8b4fe" stroke="#7e22ce" stroke-width="2"/>\n  <circle cx="330" cy="195" r="18" fill="#d8b4fe" stroke="#7e22ce" stroke-width="2"/>\n  <text x="150" y="199" text-anchor="middle" font-size="10" font-weight="bold" fill="#3b0764">Rib.1</text>\n  <text x="240" y="199" text-anchor="middle" font-size="10" font-weight="bold" fill="#3b0764">Rib.2</text>\n  <text x="330" y="199" text-anchor="middle" font-size="10" font-weight="bold" fill="#3b0764">Rib.3</text>\n  <text x="535" y="182" text-anchor="middle" font-size="12" fill="#581c87">• Tek mRNA + Çok sayıda ribozom</text>\n  <text x="535" y="202" text-anchor="middle" font-size="12" fill="#581c87">• Kısa sürede aynı çeşit proteinden</text>\n  <text x="535" y="220" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">çok sayıda kopya üretilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
